dashboard.definition:
{
	"title": "Secure Infrastructure",
	"description": "Secure Networking drill-down dashboard for Secure Infrastructure.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#0f172a",
				"strokeColor": "rgba(148,163,184,0.22)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Secure Infrastructure",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/secure-infrastructure.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e2e8f0",
				"markdown": "# Secure Infrastructure\nDevice posture, advisory exposure, SD-WAN health, and wireless infrastructure risk."
			}
		},
		"viz_infra_sdwan_edges": {
			"type": "splunk.singlevalue",
			"title": "SD-WAN Edge Sites",
			"dataSources": {
				"primary": "ds_infra_sdwan_edge_count"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('sdwan_site_count') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#0ea5e9"
			}
		},
		"viz_infra_dc_anomaly_count": {
			"type": "splunk.singlevalue",
			"title": "DC Fabric Anomalies",
			"dataSources": {
				"primary": "ds_infra_dc_anomalies"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('anomaly_count') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#f59e0b"
			}
		},
		"viz_infra_dc_advisory_count": {
			"type": "splunk.singlevalue",
			"title": "DC Security Advisories",
			"dataSources": {
				"primary": "ds_infra_dc_advisories"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('advisory_count') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#dc2626"
			}
		},
		"viz_infra_rogue_ap_count": {
			"type": "splunk.singlevalue",
			"title": "Rogue APs",
			"dataSources": {
				"primary": "ds_infra_rogue_ap_count"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('rogue_ap_count') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#dc2626"
			}
		},
		"viz_infra_dc_trend": {
			"type": "splunk.area",
			"title": "DC Health Signals Trend",
			"dataSources": {
				"primary": "ds_infra_dc_trend"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#f59e0b",
					"#dc2626"
				],
				"stackMode": "stacked",
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_infra_sdwan_apps": {
			"type": "splunk.bar",
			"title": "SD-WAN Application Health",
			"dataSources": {
				"primary": "ds_infra_sdwan_apps_health"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#16a34a",
					"#f59e0b",
					"#dc2626",
					"#64748b"
				]
			}
		},
		"viz_infra_status_rollup": {
			"type": "splunk.table",
			"title": "Infrastructure Status Rollup",
			"dataSources": {
				"primary": "ds_infra_status_rollup"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		},
		"viz_infra_psirt_exposure": {
			"type": "splunk.table",
			"title": "PSIRT Exposure by Site and Family",
			"dataSources": {
				"primary": "ds_infra_psirt_exposure"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		},
		"viz_infra_software_versions": {
			"type": "splunk.bar",
			"title": "Software Version Mix",
			"dataSources": {
				"primary": "ds_infra_software_versions"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "off",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#0ea5e9"
				]
			}
		},
		"viz_infra_rogue_containment": {
			"type": "splunk.column",
			"title": "Rogue AP Containment",
			"dataSources": {
				"primary": "ds_infra_rogue_containment"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#16a34a",
					"#dc2626"
				],
				"stackMode": "stacked"
			}
		},
		"viz_infra_secure_endpoint_incidents": {
			"type": "splunk.table",
			"title": "Secure Endpoint Incidents and Malware",
			"dataSources": {
				"primary": "ds_infra_secure_endpoint_incidents"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		},
		"viz_infra_duo_blocked_posture": {
			"type": "splunk.table",
			"title": "Duo Blocked Posture and Identity Events",
			"dataSources": {
				"primary": "ds_infra_duo_blocked_posture"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		},
		"viz_infra_duo_application_access": {
			"type": "splunk.table",
			"title": "Duo Application Access: Who, Where, and When",
			"dataSources": {
				"primary": "ds_infra_duo_application_access"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 25,
				"fontSize": "small",
				"showInternalFields": false
			}
		}
	},
	"dataSources": {
		"ds_infra_sdwan_edge_count": {
			"name": "Secure Networking - Infrastructure SD-WAN Edge Site Count",
			"options": {
				"ref": "secure_networking_infra_sdwan_edge_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_dc_anomalies": {
			"name": "Secure Networking chain - DC anomaly count",
			"options": {
				"ref": "secure_networking_dc_anomaly_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_dc_advisories": {
			"name": "Secure Networking chain - DC advisory count",
			"options": {
				"ref": "secure_networking_dc_advisory_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_rogue_ap_count": {
			"name": "Secure Networking chain - rogue AP count",
			"options": {
				"ref": "secure_networking_meraki_rogue_ap_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_dc_trend": {
			"name": "Secure Networking chain - DC health signal trend",
			"options": {
				"ref": "secure_networking_dc_health_signals_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_sdwan_apps_health": {
			"name": "Secure Networking - SD-WAN Application Health Breakdown",
			"options": {
				"ref": "secure_networking_sdwan_apps_health_breakdown",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_status_rollup": {
			"name": "Secure Networking - Secure Infrastructure Status Rollup",
			"options": {
				"ref": "secure_networking_secure_infra_status_rollup",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_psirt_exposure": {
			"name": "Secure Networking - PSIRT Exposure by Site and Family",
			"options": {
				"ref": "secure_networking_psirt_exposure_by_site_family",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_software_versions": {
			"name": "Secure Networking - Catalyst Center Software Version Inventory",
			"options": {
				"ref": "secure_networking_catalyst_center_software_version_inventory",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_rogue_containment": {
			"name": "Secure Networking chain - rogue containment",
			"options": {
				"ref": "secure_networking_meraki_rogue_ap_containment",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_secure_endpoint_incidents": {
			"name": "Secure Networking - Secure Endpoint Incident and Malware Activity",
			"options": {
				"ref": "secure_networking_infra_secure_endpoint_incidents",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_duo_blocked_posture": {
			"name": "Secure Networking - Duo Blocked Posture and Identity Events",
			"options": {
				"ref": "secure_networking_infra_duo_blocked_posture_identity",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_duo_application_access": {
			"name": "Secure Networking - Duo Application Access Detail",
			"options": {
				"ref": "secure_networking_infra_duo_application_access",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#020617",
					"display": "auto-scale",
					"height": 2310,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 90
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 9,
							"w": 72,
							"h": 72
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 120,
							"y": 0,
							"w": 1300,
							"h": 90
						},
						"type": "block"
					},
					{
						"item": "viz_infra_sdwan_edges",
						"position": {
							"x": 20,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_infra_dc_anomaly_count",
						"position": {
							"x": 375,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_infra_dc_advisory_count",
						"position": {
							"x": 730,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_infra_rogue_ap_count",
						"position": {
							"x": 1085,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_infra_dc_trend",
						"position": {
							"x": 20,
							"y": 310,
							"w": 690,
							"h": 340
						},
						"type": "block"
					},
					{
						"item": "viz_infra_sdwan_apps",
						"position": {
							"x": 730,
							"y": 310,
							"w": 690,
							"h": 340
						},
						"type": "block"
					},
					{
						"item": "viz_infra_status_rollup",
						"position": {
							"x": 20,
							"y": 670,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_infra_psirt_exposure",
						"position": {
							"x": 730,
							"y": 670,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_infra_software_versions",
						"position": {
							"x": 20,
							"y": 1080,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_infra_rogue_containment",
						"position": {
							"x": 730,
							"y": 1080,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_infra_secure_endpoint_incidents",
						"position": {
							"x": 20,
							"y": 1490,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_infra_duo_blocked_posture",
						"position": {
							"x": 730,
							"y": 1490,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_infra_duo_application_access",
						"position": {
							"x": 20,
							"y": 1900,
							"w": 1400,
							"h": 390
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
